// Extract input
const payload = msg.payload;
const allowed = payload.allowed !== false;
const schedules = payload.schedules || [];

if (!allowed || schedules.length === 0) {
    // No due schedules — skip
    return null;
}

// Process first due schedule (for demo)
const schedule = schedules[0];
const action = JSON.parse(schedule.action || '{}');

// Build commands array for viis-modbus-flex
const commands = [];
const holdingRegisters = global.get('MODBUS_HOLDING_REGISTERS') || {};
const coils = global.get('MODBUS_COILS') || {};

for (const [key, value] of Object.entries(action)) {
    if (key === 'iri_time' && !value) continue;

    if (holdingRegisters[key] !== undefined) {
        commands.push({
            fc: 6,
            unitid: 1,
            address: holdingRegisters[key],
            value: Number(value)
        });
    } else if (coils[key] !== undefined) {
        if (value === true || value === 'true' || value === 1) {
            commands.push({
                fc: 5,
                unitid: 1,
                address: coils[key],
                value: true
            });
        }
    }
}

if (commands.length === 0) {
    return null;
}

// Output for viis-modbus-flex
msg.payload = {
    commands: commands,
    schedule: schedule,
    isStarting: schedule.status !== 'running'
};

msg.topic = 'schedule-modbus-write';
return msg;

