const payload = msg.payload;
const schedule = payload.schedule;

if (!schedule) return null;

const deviceId = global.get('DEVICE_ID') || 'unknown';
const backendUrl = global.get('VIIS_BACKEND') || '';
const token = global.get('DEVICE_ACCESS_TOKEN') || '';

if (!backendUrl || !token) {
    node.warn('HTTP notification skipped: missing config');
    return null;
}

const httpPayload = {
    alarm_name: schedule.label || schedule.name,
    id: deviceId,
    msg: `Schedule ${schedule.name} ${payload.action}`,
    severity: payload.success ? 'notification' : 'error',
    trigger_time: new Date().toISOString(),
    tb_alarm_id: schedule.name,
    alarm_status: payload.action === 'start' ? 'Pending' : 'Clear',
    entity: deviceId
};

msg.method = 'POST';
msg.url = `${backendUrl}/api/v2/alarm/notification-by-token?device_access_token=${encodeURIComponent(token)}`;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = httpPayload;

return msg;

const payload = msg.payload;
const schedule = payload.schedule;

if (!schedule) return null;

const backendUrl = global.get('VIIS_BACKEND') || '';
const token = global.get('DEVICE_ACCESS_TOKEN') || '';

if (!backendUrl || !token) return null;

const now = new Date();
const today = now.toISOString().split('T')[0];

msg.method = 'POST';
msg.url = `${backendUrl}/api/v2/schedule/log?device_access_token=${encodeURIComponent(token)}`;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    start_time: `${today}T${schedule.start_time || '00:00:00'}`,
    end_time: `${today}T${schedule.end_time || '23:59:59'}`,
    schedule_id: schedule.name
};

return msg;

// Handle stuck schedule recovery from trigger output 2
const payload = msg.payload;
const recovered = payload.recoveredSchedules || [];

if (recovered.length === 0) return null;

// Build reset commands for first recovered schedule
const schedule = recovered[0];
const activeCommands = context.global.get('activeModbusCommands') || {};
const commands = activeCommands[schedule.name] || [];

const resetCommands = commands.map(cmd => ({
    fc: cmd.fc,
    unitid: cmd.unitid || 1,
    address: cmd.address,
    value: cmd.fc === 5 ? false : 0
}));

if (resetCommands.length === 0) return null;

msg.payload = {
    commands: resetCommands,
    schedule: schedule,
    isReset: true
};

return msg;
